from .message_query_function import function_on_value, function_on_field_value
from .message import MessageField


@function_on_field_value
def length(structure):
    """

    :param structure:
    :return:
    """
    return len(structure)


@function_on_value
def convert_plmn(plmn):
    """

    :param plmn:
    :return:
    """
    plmn_str = str(plmn)
    if plmn_str[2] == 'f':
        return MessageField({'mnc': [int(plmn_str[5]), int(plmn_str[4])],
                             'mcc': [int(plmn_str[1]), int(plmn_str[0]), int(plmn_str[3])]})
    return MessageField({'mnc': [int(plmn_str[5]), int(plmn_str[4]), int(plmn_str[2])],
                         'mcc': [int(plmn_str[1]), int(plmn_str[0]), int(plmn_str[3])]})
